\documentclass{article}
% A0 portrait: 841mm x 1189mm
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{array}
\usepackage{booktabs}
\pagestyle{empty}

% ── IPCC Climate Color Theme (deep navy + warm urgency accents) ──
\definecolor{primary}{HTML}{0C2340}     % deep navy
\definecolor{secondary}{HTML}{B84000}   % vermilion/amber-red
\definecolor{accent}{HTML}{1A6E8E}      % teal-blue (adaptation)
\definecolor{bgposter}{HTML}{EEF2F7}    % cool light blue-grey
\definecolor{redbg}{HTML}{FDF3ED}       % warm tint for red/orange cards
\definecolor{bluebg}{HTML}{EAF4F8}      % cool tint for blue/teal cards
\definecolor{darkbg}{HTML}{EDF0F5}      % navy tint for dark cards
\definecolor{redtitlebg}{HTML}{F5DECE}
\definecolor{bluetitlebg}{HTML}{CDEAF4}
\definecolor{darktitlebg}{HTML}{CBD3E2}
\definecolor{textdark}{HTML}{111827}
\definecolor{textgray}{HTML}{4B5563}
\definecolor{stathighlight}{HTML}{FFF0E6}
\definecolor{statblue}{HTML}{E6F0FA}
\definecolor{statgreen}{HTML}{E6F5EE}
\definecolor{statyellow}{HTML}{FFF8E6}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=22pt, itemsep=8pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=22pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Card styles ──
\tcbset{
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={6pt}{0pt}{secondary},
    left=18pt, right=16pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=redtitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={6pt}{0pt}{accent},
    left=18pt, right=16pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=bluetitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.18},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={6pt}{0pt}{primary},
    left=18pt, right=16pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=darktitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!14!white,
    borderline west={7pt}{0pt}{primary},
    left=18pt, right=16pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=6pt, bottomtitle=6pt,
    valign=top, drop shadow={opacity=0.22},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

%% ═══════════════════════════════════════════════════════
%%  TITLE BAR
%% ═══════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary,
  arc=0pt, boxrule=0pt,
  left=36pt, right=36pt, top=14pt, bottom=14pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{78}{94}\selectfont\bfseries\color{white}%
    Climate Change 2023}\\[10pt]
  {\fontsize{46}{56}\selectfont\bfseries\color{white!88}%
    Key Findings from the IPCC Sixth Assessment Synthesis Report}\\[14pt]
  {\fontsize{32}{40}\selectfont\color{white!70}%
    Intergovernmental Panel on Climate Change (IPCC) $\cdot$ AR6 Synthesis Report $\cdot$ 2023%
  }
}

%% ═══════════════════════════════════════════════════════
%%  STATS BANNER — 3 rows of 3 callouts = 6 headline metrics + 1 key message
%% ═══════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!10!white, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=8pt, bottom=8pt,
  valign=center,
  borderline south={3pt}{0pt}{primary!30},
]{name=stats, column=1, span=3, between=row4 and row8}{
  \centering
  % Row 1 of stats
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{secondary!60}{stathighlight}{\parbox{0.90\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{68}{82}\selectfont\bfseries\color{secondary} +1.1°C}\\[5pt]
      {\fontsize{26}{32}\selectfont\color{textdark} Global surface warming}\\
      {\fontsize{24}{28}\selectfont\color{textgray} 2011–2020 vs 1850–1900}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{accent!60}{statblue}{\parbox{0.90\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{68}{82}\selectfont\bfseries\color{accent} 410 ppm}\\[5pt]
      {\fontsize{26}{32}\selectfont\color{textdark} Atmospheric CO\textsubscript{2} (2019)}\\
      {\fontsize{24}{28}\selectfont\color{textgray} Highest in 2 million years}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{secondary!50}{redbg}{\parbox{0.90\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{68}{82}\selectfont\bfseries\color{secondary} 59 GtCO\textsubscript{2}e}\\[5pt]
      {\fontsize{26}{32}\selectfont\color{textdark} Annual GHG emissions}\\
      {\fontsize{24}{28}\selectfont\color{textgray} Global total in 2019}\vspace{8pt}%
    }}
  \end{minipage}

  \vspace{10pt}

  % Row 2 of stats
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{primary!50}{statblue}{\parbox{0.90\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{56}{68}\selectfont\bfseries\color{primary} 3.3–3.6B}\\[5pt]
      {\fontsize{26}{32}\selectfont\color{textdark} People exposed to}\\
      {\fontsize{24}{28}\selectfont\color{textgray} severe climate hazards}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{secondary!70}{stathighlight}{\parbox{0.90\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{68}{82}\selectfont\bfseries\color{secondary} $-$43\%}\\[5pt]
      {\fontsize{26}{32}\selectfont\color{textdark} Emissions cut needed}\\
      {\fontsize{24}{28}\selectfont\color{textgray} by 2030 for 1.5°C}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{accent!60}{statgreen}{\parbox{0.90\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{68}{82}\selectfont\bfseries\color{accent} 500 GtCO\textsubscript{2}}\\[5pt]
      {\fontsize{26}{32}\selectfont\color{textdark} Remaining carbon budget}\\
      {\fontsize{24}{28}\selectfont\color{textgray} for 1.5°C (50\% chance)}\vspace{8pt}%
    }}
  \end{minipage}
}

%% ═══════════════════════════════════════════════════════
%%  COLUMN 1 — Observed Changes + Risks
%% ═══════════════════════════════════════════════════════

\posterbox[darkcard, title={Observed Changes \& Current State}
]{name=observed, column=1, between=row8 and row13}{
  \fontsize{32}{42}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item \textbf{+1.1°C} warming already locked in — every region affected
    \item Extreme events intensifying: heatwaves, droughts, floods, cyclones
    \item Arctic sea ice area declined \textbf{$\sim$40\%} (1979–2020 Sep)
    \item Sea level rose \textbf{0.20 m} over 1901–2018
    \item Rate of change unprecedented in thousands of years
  \end{itemize}
  \vspace{10pt}
  \colorbox{secondary!20}{\parbox{0.93\linewidth}{%
    \fontsize{30}{38}\selectfont\color{textdark}\centering
    \textbf{Human influence is the principal driver} — unequivocal scientific consensus
  }}
}

\posterbox[redcard, title={Risks, Vulnerabilities \& Cascading Impacts}
]{name=risks, column=1, between=row13 and row20}{
  \fontsize{32}{42}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item \textbf{3.3–3.6 billion} people in highly vulnerable contexts
    \item Food: crop yield growth slowing; tropical fisheries declining
    \item Water: \textbf{>50\%} of world faces severe scarcity $\geq$1 month/year
    \item Health: heat mortality and vector-borne disease ranges expanding
    \item Biodiversity: 14\% terrestrial species face extinction at 1.5°C
  \end{itemize}
  \vspace{10pt}
  \colorbox{secondary!18}{\parbox{0.93\linewidth}{%
    \fontsize{29}{36}\selectfont\color{textdark}
    \textbf{Climate hazards compound with poverty, inequality, and ecosystem loss} — most vulnerable communities face greatest risk with least capacity to adapt.
  }}
}

%% ═══════════════════════════════════════════════════════
%%  COLUMN 2 — Future Projections (SSP table + bar chart style)
%% ═══════════════════════════════════════════════════════

\posterbox[bluecard, title={Future Projections: SSP Scenario Pathways}
]{name=projections, column=2, between=row8 and row15}{
  \fontsize{30}{40}\selectfont
  \vspace{4pt}
  {\fontsize{28}{36}\selectfont\color{textgray} Projected global warming by 2100 under AR6 scenarios:}
  \vspace{8pt}

  \renewcommand{\arraystretch}{1.7}
  \begin{tabular}{>{\fontsize{26}{32}\selectfont}p{0.22\linewidth}
                  >{\centering\arraybackslash\fontsize{26}{32}\selectfont}p{0.18\linewidth}
                  >{\fontsize{24}{30}\selectfont}p{0.50\linewidth}}
    \rowcolor{primary!15}
    \textbf{\color{primary}Scenario} & \textbf{\color{primary}Warming} & \textbf{\color{primary}Description} \\
    \rowcolor{accent!12}
    SSP1-1.9 & \textbf{\color{accent}$\sim$1.4°C} & Very low emissions; sustainability \\
    SSP1-2.6 & $\sim$1.8°C & Low emissions pathway \\
    \rowcolor{accent!8}
    SSP2-4.5 & $\sim$2.7°C & Intermediate emissions \\
    \rowcolor{secondary!12}
    SSP3-7.0 & $\sim$3.6°C & High emissions \\
    \rowcolor{secondary!22}
    SSP5-8.5 & \textbf{\color{secondary}$\sim$4.4°C} & Fossil-fuel intensive \\
  \end{tabular}

  \vspace{12pt}

  % Visual diverging pathway strip
  {\fontsize{27}{34}\selectfont\color{textgray}\textit{Divergence of pathways — choices made \textbf{this decade} are decisive:}}
  \vspace{8pt}

  \colorbox{accent!20}{\parbox{0.93\linewidth}{%
    \fontsize{28}{36}\selectfont\color{textdark}
    \textbf{Sea level:} +0.28–0.55 m (SSP1-1.9) vs. \textbf{+0.63–1.01 m (SSP5-8.5)} by 2100 — rise continues for centuries regardless of pathway.
  }}

  \vspace{8pt}

  \colorbox{primary!18}{\parbox{0.93\linewidth}{%
    \fontsize{28}{36}\selectfont\color{textdark}
    \textbf{Tipping points} and irreversible changes become more likely beyond 1.5–2°C of warming.
  }}
}

\posterbox[darkcard, title={Mitigation \& Adaptation Pathways}
]{name=mitigation, column=2, between=row15 and row20}{
  \fontsize{32}{42}\selectfont

  \colorbox{secondary!22}{\parbox{0.93\linewidth}{%
    \fontsize{34}{44}\selectfont\bfseries\color{textdark}\centering
    Net-zero CO\textsubscript{2} by $\sim$2050 required for 1.5°C
  }}

  \vspace{10pt}

  \begin{itemize}[itemsep=10pt]
    \item \textbf{43\% emissions reduction} below 2019 by 2030 (1.5°C path)
    \item \textbf{27\% reduction} by 2030 for 2°C pathway
    \item Rapid decarbonization of energy + electrified transport
    \item Protect \& restore carbon sinks (forests, wetlands, soils)
    \item Demand-side efficiency: cities, food, industry
  \end{itemize}

  \vspace{8pt}

  \colorbox{accent!20}{\parbox{0.93\linewidth}{%
    \fontsize{28}{36}\selectfont\color{textdark}
    Climate finance shortfall: \textbf{3–6$\times$ insufficient} for adaptation needs alone.
  }}
}

%% ═══════════════════════════════════════════════════════
%%  COLUMN 3 — Scenario Visual + Narrowing Window
%% ═══════════════════════════════════════════════════════

\posterbox[bluecard, title={Warming Trajectories by Scenario}
]{name=scenarios_visual, column=3, between=row8 and row13}{
  \fontsize{30}{40}\selectfont

  % Visual bar chart of temperature rises
  \vspace{4pt}
  \newlength{\barW}
  \setlength{\barW}{0.93\linewidth}

  {\fontsize{27}{34}\selectfont\color{textgray}\textit{Best-estimate warming by 2100 (°C above pre-industrial):}}
  \vspace{8pt}

  % SSP1-1.9
  \noindent\colorbox{accent!30}{\parbox{0.32\barW}{%
    \fontsize{26}{32}\selectfont\hspace{4pt}SSP1-1.9\hspace{4pt}}}%
  \colorbox{accent!55}{\parbox{0.04\barW}{\hspace{0pt}}}
  ~{\fontsize{28}{34}\selectfont\bfseries\color{accent}1.4°C}\par\vspace{4pt}

  % SSP1-2.6
  \noindent\colorbox{accent!20}{\parbox{0.41\barW}{%
    \fontsize{26}{32}\selectfont\hspace{4pt}SSP1-2.6\hspace{4pt}}}%
  \colorbox{accent!40}{\parbox{0.04\barW}{\hspace{0pt}}}
  ~{\fontsize{28}{34}\selectfont\bfseries\color{accent}1.8°C}\par\vspace{4pt}

  % SSP2-4.5
  \noindent\colorbox{primary!18}{\parbox{0.61\barW}{%
    \fontsize{26}{32}\selectfont\hspace{4pt}SSP2-4.5\hspace{4pt}}}%
  \colorbox{primary!30}{\parbox{0.04\barW}{\hspace{0pt}}}
  ~{\fontsize{28}{34}\selectfont\bfseries\color{primary}2.7°C}\par\vspace{4pt}

  % SSP3-7.0
  \noindent\colorbox{secondary!25}{\parbox{0.81\barW}{%
    \fontsize{26}{32}\selectfont\hspace{4pt}SSP3-7.0\hspace{4pt}}}%
  \colorbox{secondary!50}{\parbox{0.04\barW}{\hspace{0pt}}}
  ~{\fontsize{28}{34}\selectfont\bfseries\color{secondary}3.6°C}\par\vspace{4pt}

  % SSP5-8.5
  \noindent\colorbox{secondary!50}{\parbox{\barW}{%
    \fontsize{26}{32}\selectfont\hspace{4pt}\textbf{SSP5-8.5}\hspace{4pt}}}
  ~{\fontsize{28}{34}\selectfont\bfseries\color{secondary}4.4°C}\par
  \vspace{10pt}

  \colorbox{accent!20}{\parbox{0.93\linewidth}{%
    \fontsize{27}{34}\selectfont\color{textdark}
    \textbf{The 1.5°C threshold:} only SSP1-1.9 avoids dangerous climate change. Every fraction of a degree matters.
  }}
}

\posterbox[highlightcard, title={The Narrowing Window for Action}
]{name=window, column=3, between=row13 and row20}{
  \fontsize{32}{42}\selectfont

  \colorbox{secondary!22}{\parbox{0.93\linewidth}{%
    \fontsize{33}{42}\selectfont\bfseries\color{textdark}\centering
    \vspace{4pt}This decade determines whether 1.5°C or 2°C remains reachable.\vspace{4pt}
  }}

  \vspace{12pt}

  \begin{itemize}[itemsep=12pt,
    label={\color{secondary}$\blacktriangleright$}]
    \item Delayed action \textbf{locks in} high-carbon infrastructure
    \item Adaptation costs rise \textbf{sharply} beyond 1.5°C
    \item Finance flows \textbf{3–6$\times$ below} adaptation needs
    \item \textbf{Immediate, deep, sustained} reductions — all sectors
    \item \textbf{500 GtCO\textsubscript{2}} budget remaining for 1.5°C (50\% chance)
  \end{itemize}

  \vspace{10pt}

  \colorbox{primary!22}{\parbox{0.93\linewidth}{%
    \fontsize{30}{38}\selectfont\color{textdark}
    \textbf{Transition opportunities:} Solar \& wind costs fell $>$85\% (2010–2020). Mitigation feasibility is high — the barrier is ambition, not technology.
  }}

  \vspace{10pt}

  \colorbox{secondary!28}{\parbox{0.93\linewidth}{%
    \fontsize{34}{44}\selectfont\bfseries\color{secondary}\centering
    \vspace{4pt}Choices today shape the world for millennia.\vspace{4pt}
  }}

  \vspace{12pt}
  {\fontsize{28}{36}\selectfont\color{textgray}%
    \textit{Source: IPCC (2023). AR6 Synthesis Report: Climate Change 2023. Geneva: IPCC.}%
  }
}

\end{tcbposter}
\end{document}

