\usepackage{array}
\usepackage{booktabs}
\pagestyle{empty}

% ── IPCC Climate Color Theme (deep navy + warm urgency accents) ──
\definecolor{primary}{HTML}{0C2340}     % deep navy
\definecolor{secondary}{HTML}{B84000}   % vermilion/amber-red
\definecolor{accent}{HTML}{1A6E8E}      % teal-blue (adaptation)
\definecolor{bgposter}{HTML}{EEF2F7}    % cool light blue-grey
\definecolor{redbg}{HTML}{FDF3ED}       % warm tint for red/orange cards
\definecolor{bluebg}{HTML}{EAF4F8}      % cool tint for blue/teal cards
\definecolor{darkbg}{HTML}{EDF0F5}      % navy tint for dark cards
\definecolor{redtitlebg}{HTML}{F5DECE}
\definecolor{bluetitlebg}{HTML}{CDEAF4}
\definecolor{darktitlebg}{HTML}{CBD3E2}
\definecolor{textdark}{HTML}{111827}
\definecolor{textgray}{HTML}{4B5563}
\definecolor{stathighlight}{HTML}{FFF0E6}
\definecolor{statblue}{HTML}{E6F0FA}
\definecolor{statgreen}{HTML}{E6F5EE}
\definecolor{statyellow}{HTML}{FFF8E6}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=22pt, itemsep=8pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=22pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Card styles ──
\tcbset{
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
